    content: `Die Kühlkette ist das Rückgrat jeder Rohfütterung. Wer sie unterbricht, riskiert eine Keimvermehrung, die selbst für den robusten Hundemagen problematisch werden kann — und für den Halter sowieso.

## Was die Kühlkette bedeutet

Die Kühlkette beschreibt die lückenlose Kühlung von Rohfleisch: vom Einkauf über die Lagerung bis zur Verfütterung. Unterbrichst du sie — durch zu langes Stehen bei Zimmertemperatur, durch Auftauen auf der Arbeitsplatte oder durch erneutes Einfrieren — steigt die Keimzahl in kurzer Zeit erheblich.

Rohes Fleisch darf für kurze Zeit auftauen (beim Portionieren, beim Servieren), aber nicht stundenlang bei Raumtemperatur stehen.

## Lagerung: Kühlschrank und Gefrierfach

- **Frisches Rohfleisch** hält im Kühlschrank bei max. 4 °C in der Regel 1–2 Tage. Verwende es zeitnah.
- **Tiefgefrorenes Fleisch** hält bei -18 °C mehrere Monate. Das ist die Standardmethode für BARF-Vorräte.
- **Portioniert einfrieren:** Friere die Rationen direkt in der richtigen Größe ein, damit du immer genau das auftaust, was du brauchst.

## Auftauen — so richtig

**Im Kühlschrank:** Die bevorzugte Methode. Langsames Auftauen bei 4 °C begrenzt die Keimvermehrung. Je nach Portionsgröße dauert es 12–24 Stunden.

**In kaltem Wasser:** Wenn es schnell gehen muss, die verschlossene Gefriertüte in kaltes Wasser legen und mehrmals wechseln. Nie in warmem Wasser auftauen.

**Niemals:** Auf der Arbeitsplatte bei Zimmertemperatur. Niemals in der Mikrowelle (verändert die Fleischstruktur und erhitzt ungleichmäßig).

## Einmal aufgetaut — nicht wieder einfrieren

Das erneute Einfrieren von aufgetautem Fleisch ist problematisch: Die Keimzahl steigt beim Auftauen. Wird das Fleisch dann wieder eingefroren und später noch einmal aufgetaut, summieren sich die Risiken. Plane deine Portionen so, dass du nichts übrig hast.

## Beim Einkauf an die Kühlkette denken

Kaufe Rohfleisch möglichst zuletzt ein und bring es schnell nach Hause. An heißen Sommertagen eine Kühltasche mitnehmen. Wenn du größere Mengen online bestellst: prüfe, ob die Ware tiefgekühlt geliefert wird und nimm die Pakete sofort entgegen.

## Häufige Fragen

### Wie lange kann aufgetautes Fleisch im Kühlschrank bleiben?
Aufgetautes Rohfleisch sollte innerhalb von 24 Stunden verfüttert werden. Keimvermehrung im Kühlschrank ist zwar langsamer, aber nicht null.

### Kann ich Fleisch aus dem Supermarkt einfrieren?
Ja, grundsätzlich schon — solange das MHD noch nicht abgelaufen ist. Überprüfe das Datum und friere das Fleisch zeitnah nach dem Kauf ein, wenn du es nicht sofort verfütterst.

### Muss tiefgefrorenes Fleisch erst aufgetaut werden?
Ja. Direkt aus dem Gefrierfach in den Napf ist keine gute Idee — kaltes Fleisch kann den Magen belasten. Lass es erst vollständig im Kühlschrank auftauen.

## Das Wichtigste in Kürze

- Rohfleisch immer durchgehend kühlen oder gefroren lagern.
- Auftauen im Kühlschrank ist die sicherste Methode.
- Aufgetautes Fleisch nicht wieder einfrieren.
- Portioniert einfrieren spart Zeit und vermeidet Reste.`,
