    imageUrl: "/images/tipps/barf/7.jpg",
    imageAlt: "Portionierte BARF-Pakete beschriftet im Gefrierfach",
    content: `Wer BARF nicht täglich frisch einkaufen kann oder will, kommt um das Einfrieren nicht herum. Das Portionieren vor dem Einfrieren ist dabei nicht nur praktisch — es ist ein Schlüssel für Hygiene, Genauigkeit und einen stressfreien BARF-Alltag.

## Warum portioniert einfrieren?

Die Alternative — ein großes Stück Fleisch einfrieren und jeweils abschneiden — hat mehrere Nachteile:
- Du musst frisches Fleisch einfrieren und dabei Teilstücke auftauen.
- Erneutes Einfrieren von aufgetautem Fleisch ist nicht ratsam.
- Die Abwiege-Arbeit fällt täglich statt nur einmal an.

Wenn du die Wochenrationen direkt portionierst und einfrierst, entnimmst du täglich nur das, was gebraucht wird — nichts mehr.

## Das richtige Behältnis

- **Zip-Beutel:** Platzsparend, gut stapelbar, günstig. Entlüfte sie so weit wie möglich.
- **Vakuumierbeutel:** Noch besser für die Haltbarkeit, weniger Gefrierbrand, ideal für größere Vorräte.
- **Gefrierboxen:** Praktisch, aber nehmen mehr Platz weg und der Deckel kann offen bleiben.

**Wichtig:** Immer beschriften — Fleischsorte, Gewicht, Datum. Was nicht beschriftet ist, wird nicht verfüttert, weil du nicht mehr weißt, was drin ist.

## Schritt für Schritt

1. Fleisch nach Einkauf direkt portionieren (kalt bleiben, nicht lange bei Zimmertemperatur).
2. Jede Portion auf der Waage abwiegen — z. B. eine Tagesration pro Beutel.
3. Beschriften: Sorte + Gramm + Datum.
4. In der Gefriertruhe oder dem Tiefkühlfach verstauen.
5. Abends für den nächsten Tag eine Portion in den Kühlschrank stellen.

## Wie lange hält Rohfleisch eingefroren?

Als Faustregel gilt bei -18 °C:
- **Rind, Lamm, Wild:** bis zu 6 Monate
- **Geflügel:** 3–4 Monate
- **Fisch:** 2–3 Monate
- **Innereien:** 2–3 Monate

Nach längerer Lagerung verändert sich die Qualität (Gefrierbrand, Textur), auch wenn das Fleisch nicht verdorben ist.

## Praktische Alltagstipps

- Bereite Vorräte für 1–2 Wochen auf einmal vor. Das spart Zeit und Aufwand.
- Stelle die Portionen in einer klaren Reihenfolge ins Gefrierfach — ältere Portionen vorne, neuere hinten (FIFO-Prinzip).
- Wenn du verschiedene Fleischsorten wechselst, trenne die Beutel nach Sorte.

## Häufige Fragen

### Kann ich mehrere Komponenten zusammen einfrieren?
Ja, viele BARFer frieren Fleisch und Gemüse zusammen in einer Portion ein. Innereien besser separat, da sie empfindlicher sind.

### Darf ich eingefrorenes Fleisch direkt aus dem Laden tiefkühlen?
Ja, solange das MHD noch gilt und die Kühlkette nicht unterbrochen war. Friere es zeitnah nach dem Kauf ein.

### Wie erkenne ich Gefrierbrand?
Trockene, grau-weiße Stellen auf dem Fleisch. Es ist nicht verdorben, schmeckt aber weniger gut. Mit Vakuumieren lässt sich Gefrierbrand stark reduzieren.

## Das Wichtigste in Kürze

- Immer portioniert einfrieren — eine Portion pro Tagesration.
- Behältnisse beschriften: Sorte, Gramm, Datum.
- FIFO nutzen: Ältere Portionen zuerst verfüttern.
- Auftauen über Nacht im Kühlschrank — nie bei Zimmertemperatur.`,
