    id: 18,
    slug: "obst-nur-sparsam",
    title: "Obst nur sparsam einsetzen",
    shortDescription:
      "Etwas Apfel oder Beeren sind okay, aber zuckerhaltig. Obst ist eine kleine Ergänzung, kein Hauptbestandteil.",
    level: 1,
    tags: ["obst", "zusammensetzung"],
    imageUrl: "/images/tipps/barf/18.jpg",
    imageAlt: "Kleines Stück Apfel als BARF-Ergänzung für den Hund",
    content: `Obst in der Hundernährung hat seinen Platz — aber einen kleinen. Wer es übertreibt, füttert vor allem Zucker. Wer es ganz weglässt, verpasst nichts Kritisches. Die richtige Haltung: Obst als gelegentliche, kleine Ergänzung, nicht als Grundbestandteil.

## Was Obst liefert

Obst enthält:
- Vitamin C (Hunde können es selbst produzieren, aber ein wenig extra ist harmlos)
- Antioxidantien (besonders Beeren)
- Fruchtzucker (Fructose) — das ist der springende Punkt

Der Zuckergehalt variiert stark: Beeren sind zuckerärmer, Trauben (ohnehin giftig!) und Bananen zuckerreicher. Für einen gesunden Hund macht ein kleiner Obstanteil wenig aus. Bei übergewichtigen Hunden oder Diabetikern ist Obst aber ein Faktor, den man mit dem Tierarzt besprechen sollte.

## Welches Obst ist geeignet?

**Gut geeignet:**
- Apfel (ohne Kerne und Kerngehäuse — Kerne enthalten Blausäure)
- Blaubeeren, Heidelbeeren
- Himbeeren, Brombeeren
- Erdbeeren
- Wassermelone (ohne Schale und Kerne)
- Birne (ohne Kerne)

**Tabu:**
- **Weintrauben und Rosinen:** Hochgiftig für Hunde, auch in kleinen Mengen.
- **Kirschen:** Kerne giftig, Frucht selbst umstritten.
- **Zitrusfrüchte:** In großen Mengen magenreizend.
- **Avocado:** Giftig (Persin).

## Wie viel ist sparsam?

In einer typischen BARF-Ration reicht ein Anteil von 1–5 % für gelegentliches Obst — also bei 400 g Tagesration etwa 5–20 g. Das ist ein kleiner Löffel Blaubeeren oder ein paar Apfelscheiben.

Manche Pläne enthalten kein Obst — das ist absolut in Ordnung. Obst ist kein Pflichtbestandteil.

## Obst frisch oder eingefroren?

Beides geht. Eingefroren sogar praktisch als Sommersnack — viele Hunde knabbern gerne an gefrorenen Beeren. Achte darauf, dass kein Konservierungsmittel oder Zuckerzusatz enthalten ist.

## Häufige Fragen

### Darf mein Hund Bananen essen?
Bananen sind nicht giftig, aber sehr zuckerreich. Für gelegentliche kleine Stücke kein Problem, aber keine regelmäßige Ergänzung für die BARF-Ration.

### Mein Hund liebt Äpfel. Darf er so viele er will?
Nicht ganz — Äpfel enthalten Fruchtzucker. Größere Mengen können Magen und Darm belasten und sind für übergewichtige Hunde suboptimal. Ein bis zwei Scheiben täglich sind unproblematisch.

### Was passiert, wenn mein Hund versehentlich Weintrauben gefressen hat?
Sofort den Tierarzt kontaktieren. Weintrauben können zu Nierenversagen führen. Nicht abwarten.

## Das Wichtigste in Kürze

- Obst ist kein Pflichtbestandteil der BARF-Ration, aber eine feine Ergänzung.
- Zuckergehalt beachten: Beeren sind die bessere Wahl als zuckerreiche Früchte.
- Weintrauben, Rosinen und Avocado sind für Hunde hochgiftig — niemals verfüttern.
- Maximal 5 % der Ration, das entspricht ein paar Scheiben oder einem Löffel Beeren.`,
