    id: 26,
    slug: "maengel-ernst-nehmen",
    title: "Mängel ernst nehmen",
    shortDescription:
      "Langfristig unausgewogenes BARF führt zu Mängeln, die sich erst spät zeigen. Regelmäßige Blutkontrollen geben Sicherheit.",
