    slug: "welpen-barf-planen",
    title: "Welpen-BARF besonders sorgfältig planen",
    shortDescription:
      "Wachsende Hunde haben einen sensiblen Bedarf, besonders bei Kalzium. Welpen-BARF gehört unbedingt fachlich berechnet.",
