      "Reinige den Napf nach jeder Mahlzeit gründlich. Rohfleischreste werden schnell zur Keimquelle.",
    level: 0,
    tags: ["hygiene", "napf"],
    imageUrl: "/images/tipps/barf/8.jpg",
    imageAlt: "Hundenapf wird nach BARF-Mahlzeit gründlich gereinigt",
    content: `Ein übersehener Punkt im BARF-Alltag: der Napf. Rohfleischreste im Napf sind ein ideales Nährmedium für Bakterien — und bleiben häufig stundenlang stehen, weil der Napf erst beim nächsten Füttern gespült wird. Das ist eine unnötige Keimquelle.

## Was im Napf passiert

Wenn rohes Fleisch im Napf liegt oder Reste davon zurückbleiben, beginnt sofort der Abbau durch Bakterien. Bei Zimmertemperatur passiert das erstaunlich schnell — innerhalb von Stunden können sich Keime wie Salmonellen und Campylobacter erheblich vermehren.

Der Hund leckt seinen Napf auch nach der Mahlzeit weiter ab. Die Schnauze berührt danach alles: Dein Gesicht, den Fußboden, das Spielzeug deiner Kinder.

## Was du nach jeder Mahlzeit tun solltest

1. **Stehenlassen vermeiden:** Was der Hund in 20 Minuten nicht gefressen hat, kommt weg oder wird gut gekühlt aufbewahrt.
2. **Napf sofort abspülen:** Heißes Wasser und Spülmittel — nicht erst Stunden später.
3. **Gründlich schrubben:** Nicht nur kurz abspülen. Rohfleischfette kleben an der Napfwand.
4. **Trocknen lassen:** Ein feuchter Napf bildet schnell Keimfilm.

## Das richtige Napfmaterial

- **Edelstahl:** Robust, keimarm, spülmaschinengeeignet. Beste Wahl für BARF.
- **Keramik:** Ebenfalls gut, wenn ungesprungen und glasiert.
- **Plastik:** Kratzt leicht — in Mikrokratzern nisten sich Keime ein. Für BARF weniger geeignet.

Plastiknapfe regelmäßig auf Kratzer prüfen und bei Beschädigung austauschen.

## Spülmaschine vs. Handwaschen

Spülmaschine ist ideal: Die hohen Temperaturen töten Keime zuverlässiger als Handwäsche. Wenn du täglich spülst, reicht abwechselndes Handwaschen und wöchentliche Spülmaschine.

## Häufige Fragen

### Wie oft muss der Napf wirklich gereinigt werden?
Nach jeder BARF-Mahlzeit. Bei Nassfutter oder Trockenfutter kann man es etwas lockerer sehen — bei Rohfleisch nicht.

### Was ist mit Wassernapf?
Täglich frisches Wasser, Napf täglich spülen. Schleim- und Biofilmbildung im Wassernapf ist ein Keimproblem, das oft unterschätzt wird.

### Muss ich den Futterplatz auch reinigen?
Wenn Fleischsaft oder Reste auf den Boden gefallen sind: sofort wischen. Eine abwischbare Unterlage unter dem Napf hilft enorm.

## Das Wichtigste in Kürze

- Nach jeder Rohfleisch-Mahlzeit den Napf heiß und gründlich spülen.
- Edelstahl oder glasierte Keramik sind die hygienischsten Napfmaterialien.
- Spülmaschine ist die zuverlässigste Reinigungsmethode.
- Reste nicht stundenlang im Napf lassen — sofort kühlen oder entsorgen.`,
