    imageAlt: "Fetthaltige Fleischteile für Hunde — Fettmenge beim BARFen",
    content: `Fett ist beim BARFen kein Feind — es ist ein wichtiger Energieträger und Träger fettlöslicher Vitamine. Aber: Zu viel Fett ist einer der häufigsten Fehler, die Rohfütterer machen — besonders am Anfang.

## Welche Rolle Fett in der BARF-Ration spielt

Fette liefern:
- Energie (mehr als doppelt so viel pro Gramm wie Protein oder Kohlenhydrate)
- Essentielle Fettsäuren (Omega-3, Omega-6) für Haut, Fell und Zellfunktionen
- Träger für die Vitamine A, D, E und K

Das heißt: Eine gewisse Fettmenge ist absolut notwendig. Das Problem ist das Zuviel.

## Was passiert bei zu viel Fett?

- **Kurzfristig:** Weicher Kot bis Durchfall, fettige Kotstreifen, Bauchgurgeln
- **Mittelfristig:** Übergewicht, da die Energiemenge der Ration zu hoch ist
- **Langfristig:** Erhöhtes Risiko für Pankreatitis (Bauchspeicheldrüsenentzündung), besonders bei empfindlichen Rassen

## Wie viel Fett ist vertretbar?

Grobe Orientierung: Ein Fettgehalt von 10–20 % der Trockenmasseenergie gilt für durchschnittliche erwachsene Hunde als vertretbar. Aktive Hunde können etwas mehr, übergewichtige oder pankreassensible Hunde deutlich weniger vertragen.

In der Praxis bedeutet das: **Fettes Muskelfleisch, Bauchlappen oder Speck** sollte nicht den Hauptanteil ausmachen. Mageres Fleisch (Hühnerbrust, Rindergulasch, Kaninchen) als Basis, Fett gezielt ergänzen.

## Welche Fleischteile sind besonders fettreich?

- Schweinebauch, Lammfleisch (oft sehr fett), Rinderbauchlappen
- Haut von Geflügel
- Fettreicher Fisch (Lachs, Makrele, Hering — gut für Omega-3, aber portioniert)

## Häufige Fragen

### Wie erkenne ich, ob die Ration zu fett ist?
Der Kot ist ein guter Indikator: glänzend, fettig, weich oder gelblich — das deutet auf zu viel Fett hin. Auch Aufstößen nach dem Fressen kann ein Zeichen sein.

### Soll ich Fleisch entfetten?
Nicht vollständig, aber bei sehr fetten Stücken kannst du sichtbares Fett teilweise entfernen. Eine fettarme Basis mit gezielter Ölergänzung ist oft besser steuerbar.

### Ist Lachs trotz Fettgehalts empfehlenswert?
Ja — Lachs und andere fette Seefische sind wegen ihrer Omega-3-Fettsäuren wertvoll. Aber dosiert und als Ergänzung, nicht als Hauptquelle.`,
