    slug: "ballaststoffe-fuer-den-darm",
    title: "Den Bedarf an Ballaststoffen decken",
    shortDescription: "Etwas pürierte Pflanzen oder Flohsamen liefern Ballaststoffe für eine gesunde Darmtätigkeit.",
