    imageUrl: "/images/tipps/barf/20.jpg",
    imageAlt: "Hund wird gewogen — Gewichtskontrolle beim BARFen",
    content: `Beim BARF gibt es keine Fütterungsempfehlung auf der Packung. Du bist derjenige, der entscheidet — und das setzt voraus, dass du weißt, ob die Menge stimmt. Regelmäßiges Wiegen ist das einfachste und zuverlässigste Kontrollwerkzeug.

## Warum BARF leicht fehl dosiert wird

Fertigfutter hat eine aufgedruckte Tabelle: „Hund 10 kg → 200 g pro Tag". BARF hat eine Formel: 2–3 % des Körpergewichts. Klingt einfach, aber:

- 2 % von 10 kg = 200 g vs. 3 % von 10 kg = 300 g — ein erheblicher Unterschied im Jahresschnitt
- Fleisch ist nicht gleich Fleisch: Fettreiche Sorten haben viel mehr Kalorien als magere
- Aktivität, Jahreszeit und Alter beeinflussen den Bedarf kontinuierlich

Das Gewicht ist das ehrlichste Feedback, das du bekommst.

## Wie oft wiegen?

- **Einstiegsphase (erste 4 Wochen):** Wöchentlich
- **Eingespielte Ration:** Alle 2–4 Wochen
- **Veränderungen (Alter, Aktivität, Krankheit):** Häufiger

## Wie wiegen?

Kleine Hunde: Auf eine Personenwaage steigen, Hund halten, eigenes Gewicht abziehen.
Mittlere und große Hunde: Tierarztwaage (oft kostenlos nutzbar im Wartezimmer), oder Hundewaage kaufen.

Immer zur selben Tageszeit wiegen, am besten morgens nüchtern — das minimiert Tagesschwankungen durch Mageninhalt.

## Was das Gewicht dir sagt

- **Steigendes Gewicht:** Zu viel Futter oder zu fettreich — Menge reduzieren
- **Sinkendes Gewicht:** Zu wenig Futter oder zu magere Zusammensetzung — Menge erhöhen oder fettreichere Anteile ergänzen
- **Stabiles Gewicht im Zielkorridor:** Ration passt

Ergänze Wiegen mit Sichtkontrolle: Rippen sollten bei leichtem Druck tastbar, aber nicht sichtbar sein. Keine Taille sichtbar oder Rippen sehen = zu dick/zu dünn.

## Häufige Fragen

### Wie viel Gewichtsschwankung ist normal?
Bei kleinen Hunden schon 100–200 g Unterschied können relevant sein. Bei großen Hunden ist ein Korridor von 1–2 kg über Wochen oft normal — längerfristige Trends zählen mehr als Tagesschwankungen.

### Wann sollte ich zum Tierarzt?
Bei unerklärlichem rapidem Gewichtsverlust (mehr als 5 % in zwei Wochen ohne Diätabsicht) oder starker Gewichtszunahme trotz Reduzierung immer tierärztlich abklären.

### Ist das Körperkonditionsscoring besser als Wiegen?
BCS (Body Condition Score) und Waage ergänzen sich. BCS beurteilt Fettverteilung und Muskelanteil — etwas subjektiver, aber wertvoll zusätzlich zur Waage.`,
