    imageAlt: "Hund mit Magenproblemen — Durchfall beim BARFen prüfen",
    content: `Durchfall beim BARFen ist kein seltenes Problem — und in den meisten Fällen ein Signal, das du verstehen und beheben kannst. Vorausgesetzt, du weißt, woran es liegt.

## Die häufigsten Ursachen für Durchfall beim BARFen

**1. Zu viele Innereien**
Leber, Niere und andere Innereien sind reich an Nährstoffen — aber auch an Vitamin A und fettlöslichen Substanzen, die in hoher Dosis abführend wirken. Übliche Empfehlung: Innereien max. 10–15 % der Ration, Leber davon höchstens die Hälfte.

**2. Zu viel Fett**
Fettreiche Fleischteile, zu viel Öl oder ein plötzlich fettreiches Stück treiben die Darmpassage an. Weicher, glänzender, fettiger Kot ist ein typisches Zeichen.

**3. Zu schnelle Umstellung**
Der Darm braucht Zeit, neue Enzyme für Rohfutter zu bilden. Wer in wenigen Tagen komplett umstellt, überlastet das Verdauungssystem.

**4. Neue Fleischsorte**
Jede neue Proteinquelle kann vorübergehend zu weichem Kot führen, besonders wenn der Hund sie noch nicht kennt.

**5. Qualitätsproblem**
Angewandeltes Fleisch, abgelaufene Produkte oder Keimbelastung können ebenfalls Durchfall auslösen.

## Was du tun kannst

- **Ration vereinfachen:** Reduziere vorübergehend auf eine magere Fleischsorte ohne Innereien
- **Fettmenge senken:** Prüfe, ob ein besonders fettiges Stück die Ursache ist
- **Umstellungsgeschwindigkeit reduzieren:** Wenn du gerade umstellst, verlangsame das Tempo
- **Neue Komponenten stoppen:** Führe nichts Neues ein, bis die Verdauung sich stabilisiert hat

## Wann zum Tierarzt?

- Anhaltender Durchfall über 48 Stunden
- Blut im Kot
- Erbrechen zusätzlich
- Starke Lethargie oder Schmerzsymptome

## Häufige Fragen

### Hilft Fasten bei BARF-Durchfall?
Kurze Fastenperiode (12–24 Stunden, Wasser anbieten) kann bei mildem Durchfall helfen. Danach mit kleinen Mengen leicht verdaulichem Fleisch (Hühnerbrust, Pute) starten.

### Sollte ich Leckerlis und Snacks ausschließen?
Ja, beim Debuggen der Ration. Snacks können ebenfalls Auslöser sein.

### Kann ich Probiotika einsetzen?
Probiotika für Hunde können die Darmflora bei Umstellungsdurchfall stabilisieren — ein sinnvoller Zusatz in der Anfangsphase.`,
