    imageAlt: "Harter Kot beim BARFen — Knochen reduzieren",
    content: `Knochenkot — weißlich, kreidefarben, sehr hart und bröselnd — ist das klassische Zeichen eines zu hohen Knochenanteils in der BARF-Ration. Viele Einsteiger machen diesen Fehler, und der Kot zeigt es zuverlässig.

## Warum zu viel Knochen problematisch ist

Knochen bestehen hauptsächlich aus Kalzium und Phosphor. Ein übermäßiger Knochenanteil führt zu:
- **Hartem, weißlichem Kot:** Calciumüberschuss bindet Wasser im Darm
- **Verstopfung:** Im schlimmsten Fall kann der Hund keinen Kot mehr absetzen
- **Langfristig:** Kalziumüberversorgung, die bei wachsenden Hunden Skelettschäden verursachen kann

Kurzes Anzeichen für zu viel Knochen ist nicht gefährlich. Anhaltend sehr harter Kot, Würgen beim Kotabsatz oder gar keine Kotabsatz sollten sofort zum Handeln führen.

## Was der ideale BARF-Kot aussieht

- Mittelbraun bis dunkelbraun
- Fest, aber nicht steinhart
- Lässt sich aufsammeln ohne zu zerkrümeln
- Kleine bis moderate Menge (weniger als bei Trockenfutter, da BARF sehr verdaulich ist)

## Wie du den Knochenanteil anpasst

Reduziere zuerst die fleischigen Knochen (z. B. Hühnerrücken, Rinderrippen) in der Ration. Wenn du Knochen als Kalziumquelle nutzt: Wechsle teilweise auf Eierschalenmehl oder Calciumcarbonat, bis sich der Kot normalisiert.

Faustregel: Knochen sollten 10–15 % der Gesamtration ausmachen — nicht mehr.

## Was bei Verstopfung tun?

- Mehr Flüssigkeit (zusätzliches Wasser anbieten)
- Etwas Kürbispüree (ballaststoff- und wasserreich)
- Knochen aus der Ration streichen, bis die Situation sich klärt
- Bei echtem Kotabsatzproblem: Tierarzt aufsuchen

## Häufige Fragen

### Wie schnell normalisiert sich der Kot nach Knochenreduktion?
In der Regel innerhalb von 1–3 Tagen nach Anpassung der Ration.

### Muss ich Knochen ganz weglassen?
Nein — Knochen sind wertvoll. Nur die Menge muss stimmen. Richtig dosiert sind sie eine gute Kalziumquelle und Beschäftigung.

### Was, wenn der Hund keinen Knochen annimmt?
Dann ist Eierschalenmehl oder Calciumcarbonat die unkompliziertere Alternative als Kalziumquelle.`,
