    slug: "wasserbedarf-beim-barfen",
    title: "Den Wasserbedarf beachten",
    shortDescription: "Rohfutter enthält viel Feuchtigkeit, dennoch braucht der Hund freien Zugang zu Wasser.",
    level: 0,
    tags: ["wasser", "hydration"],
    imageUrl: "/images/tipps/barf/5.jpg",
    imageAlt: "Hund trinkt Wasser — Hydration beim BARFen",
    content: `Rohfutter ist wasserhaltiger als Trockenfutter — das stimmt. Trotzdem braucht jeder Hund, der BARF bekommt, freien und dauerhaften Zugang zu frischem Wasser. Wasser ist kein Luxus, sondern eine Grundvoraussetzung für Gesundheit.

## Wie viel Wasser steckt in Rohfutter?

Frisches Rohfleisch enthält je nach Sorte 65–75 % Wasser. Zum Vergleich: Trockenfutter enthält nur 6–10 % Wasser. Das bedeutet, dass BARFende Hunde über das Futter einen erheblichen Teil ihres täglichen Wasserbedarfs decken.

Das heißt aber nicht, dass sie keinen separaten Wassernapf brauchen. Der Mehrbedarf bei körperlicher Aktivität, Hitze oder Krankheit muss über freies Trinken gedeckt werden können.

## Was passiert bei zu wenig Wasser?

Dehydration — selbst leichte — hat Auswirkungen auf:
- Nierenfunktion (besonders bei rohfleischreicher Diät mit hoher Stickstofflast)
- Darmtätigkeit (Verstopfung bei zu wenig Flüssigkeit plus viel Knochen)
- Kreislauf und Körpertemperaturregulation

## Beobachte die Trinkmenge

BARFende Hunde trinken oft weniger als Trockenfutterhunde — das ist normal und kein Alarmsignal. Aber:

- Kein Trinken über einen Tag: Beobachten und Wasserangebot prüfen
- Stark erhöhtes Trinken (Polydipsie): Kann auf Nieren-, Leber- oder Hormonprobleme hinweisen — tierärztlich abklären

## Napfhygiene beim Wassernapf

Wassernapf täglich spülen, mehrmals wöchentlich gründlich reinigen. Stehende Wasserbecken bilden schnell Biofilm, besonders im Sommer.

## Häufige Fragen

### Muss ich beim BARFen zusätzliches Wasser ins Futter mischen?
Nein, das ist nicht nötig. Der natürliche Feuchtigkeitsgehalt des Rohfleischs reicht aus. Zusätzliches Wasser wird nicht empfohlen, da es die Nährstoffkonzentrationen verdünnt.

### Darf der Napf auch immer leer sein?
Nein. Wasser muss dauerhaft verfügbar sein — jederzeit und in ausreichender Menge.

### Ist Leitungswasser in Deutschland geeignet?
Ja. Deutsches Leitungswasser ist Lebensmittelqualität und für Hunde geeignet. Gefiltertes Wasser ist kein Muss, aber vertretbar.`,
