    imageAlt: "Nahrungsergänzungsmittel für BARFende Hunde",
    content: `Wer BARF selbst zusammenstellt, stößt schnell auf die Frage: Welche Ergänzungen brauche ich? Die Antwort ist differenzierter als „je mehr, desto besser" — und auch das Gegenteil gilt: „lieber weglassen" ist nur dann richtig, wenn du genau weißt, dass eine Komponente bereits gedeckt ist.

## Warum Ergänzungen beim BARFen oft notwendig sind

Reines Rohfleisch deckt den Bedarf eines Hundes nicht vollständig. Bestimmte Nährstoffe kommen in Fleisch kaum oder gar nicht vor:

- **Jod:** Fast nicht in Fleisch enthalten — Quelle: Seealgenmehl oder jodhaltiger Mineralstoff
- **Kalzium:** Fehlt, wenn keine Knochen gegeben werden — Quelle: Eierschalenmehl, Calciumcarbonat
- **Vitamin D:** Nur in Fisch und Leber ausreichend — bei fleischlastiger Ration supplementieren
- **Omega-3 (EPA/DHA):** Nur in fettem Seefisch ausreichend — Quelle: Lachsöl, Hering

## Was du bei Supplements beachten musst

- **Nach Plan dosieren:** Nicht nach Bauchgefühl. Zu viel von fettlöslichen Vitaminen (A, D, E, K) ist giftig
- **Nicht doppelt ergänzen:** Wenn du bereits Fisch fütterst, brauchst du kein extra Omega-3 mehr in voller Dosis
- **Qualität wählen:** Humanqualität oder tierärztlich zugelassene Produkte

## Gängige BARF-Ergänzungen im Überblick

| Supplement | Zweck | Dosierung (Orientierung) |
|---|---|---|
| Seealgenmehl | Jod | 1–3 g / Woche für 10 kg KG |
| Eierschalenmehl | Kalzium | ~1 g / 10 kg KG / Tag (wenn keine Knochen) |
| Lachsöl | Omega-3 | 1 ml / 10 kg KG / Tag |
| Vitamin E | Antioxidans, Fettschutz | 1–2 mg / kg KG / Tag |
| Vitamin D3 | Knochengesundheit | nur nach tierärztlicher Messung |

## Häufige Fragen

### Muss ich alle Supplements täglich geben?
Nein. Manche werden täglich gegeben (Öle), andere wöchentlich (Algen). Verteilung ist wichtiger als tägliche Gabe bei allen.

### Kann ich eine fertige Mineralstoffmischung verwenden?
Ja — wenn sie für die Rohfütterung formuliert und die Berechnung auf deinen Hund abgestimmt ist. Überprüf, ob sie wirklich alle Lücken schließt.

### Was ist mit Probiotika?
Probiotika können die Darmflora bei der Umstellung unterstützen, sind aber keine Dauerergänzung, die jeder BARF-Hund braucht.`,
