    imageAlt: "BARF-Ration dokumentieren und aufschreiben",
    content: `BARF ist kein Fertigprodukt mit aufgedruckter Zusammensetzung. Du bist der Hersteller. Und wie jeder Hersteller solltest du eine Dokumentation haben — nicht aus Bürokratie, sondern weil sie dir und deinem Hund nützt.

## Warum Dokumentation beim BARFen sinnvoll ist

Ohne Aufzeichnungen passiert Folgendes:
- Du änderst die Ration schrittweise, ohne es zu merken (Drift)
- Bei Problemen weißt du nicht, was sich wann geändert hat
- Beim Tierarztbesuch kannst du keine konkreten Angaben machen
- Du musst die Berechnung jedes Mal neu machen

Mit einer kurzen Dokumentation hast du:
- Eine reproduzierbare Basis
- Eine Fehlersuche-Grundlage bei Problemen
- Einen Vergleich über Zeit (Körpergewicht, Kotqualität, Energielevel)

## Was du festhalten solltest

Minimaler Aufwand, maximaler Nutzen:

1. **Zusammensetzung:** Welches Fleisch (Sorte + Menge), welche Innereien (Sorte + Menge), Knochen/Kalziumquelle, Pflanzliche Anteile, Ergänzungen
2. **Tagesmenge:** Gesamtgewicht der Tagesration
3. **Datum der letzten Änderung**
4. **Gewicht des Hundes** (monatlich)
5. **Kurze Notizen zu Kotqualität, Fell, Energie**

## Womit du dokumentierst

- **Papier:** Einfach und datenschutzkonform — ein kleines Notizbuch reicht
- **Tabellenkalkulation:** Ideal für Berechnungen und Gewichtsverläufe
- **BARF-Apps:** Es gibt Apps speziell für Rohfütterung (z. B. BARF-Rechner-Apps), die Nährstoffberechnungen mitführen

## Häufige Fragen

### Muss ich jeden Tag alles aufschreiben?
Nein. Bei konstanter Ration reicht es, Änderungen zu notieren. Bei der Neuberechnung oder nach Problemen: genauer dokumentieren.

### Was tue ich mit der Dokumentation beim Tierarzt?
Eine kurze Übersicht der Ration ist für den Tierarzt sehr hilfreich — besonders wenn Blutuntersuchungen ausgewertet oder Probleme diskutiert werden sollen.

### Kann ich die Ration auch in einem Online-Rechner speichern?
Ja — viele Online-BARF-Rechner haben Speicherfunktionen. Achte darauf, dass die Daten nicht verloren gehen.`,
