    slug: "bei-krankheit-barf-ueberdenken",
    title: "Bei Krankheit BARF überdenken",
    shortDescription: "Bei bestimmten Erkrankungen kann Rohfütterung ungeeignet sein. Sprich es mit dem Tierarzt ab.",
    level: 2,
    tags: ["krankheit", "sicherheit"],
    imageUrl: "/images/tipps/barf/11.jpg",
    imageAlt: "Kranker Hund — BARF bei Erkrankungen überdenken",
    content: `BARF ist für gesunde Hunde in den meisten Fällen eine vertretbare Fütterungsform — wenn sie fachlich korrekt umgesetzt wird. Bei bestimmten Erkrankungen ändert sich diese Aussage jedoch deutlich. Rohfütterung muss dann neu bewertet oder eingestellt werden.

## Erkrankungen, bei denen BARF kritisch ist

**Niereninsuffizienz:**
Hunde mit eingeschränkter Nierenfunktion brauchen eine phosphorarme, oft auch proteinreduzierte Diät. Reines Rohfleisch ist sehr phosphorreich — das belastet die Nieren zusätzlich. Spezialdiäten sind hier Pflicht, und die wenigsten lassen sich mit BARF umsetzen.

**Pankreatitis (Bauchspeicheldrüsenentzündung):**
In der akuten Phase ist strenge Fettreduktion erforderlich. Rohfleisch mit natürlichem Fettgehalt ist kaum kontrollierbar genug für diese Diät.

**Immunsuppression:**
Hunde nach Chemotherapie, mit HIV-ähnlichen Erkrankungen oder nach Organtransplantationen können rohe Fleischkeime nicht sicher bekämpfen.

**Lebererkrankungen:**
Je nach Art der Lebererkrankung können hohe Proteinmengen das Problem verschlimmern.

**Bestimmte Krebserkrankungen:**
Je nach Tumorart und Behandlung kann der Arzt spezifische Diäten empfehlen, die sich nicht mit rohem Fleisch vereinbaren lassen.

## Was du in einer Krankheitsphase tun solltest

1. Tierarzt über die Rohfütterung informieren
2. Ggf. auf eine therapeutische Diät umstellen
3. BARF nicht eigenmächtig bei chronischen Erkrankungen weiterführen, wenn du keine fundierte Aussage des Tierarztes dazu hast
4. Nach überstandener Erkrankung: Rückkehr zu BARF gemeinsam planen

## Häufige Fragen

### Muss ich beim ersten Husten aufhören zu BARFen?
Nein. Leichte Erkrankungen (Erkältung, Magen-Darm-Infekt) erfordern in der Regel keine Ernährungsumstellung, höchstens eine schonende Kost für einige Tage.

### Kann BARF Erkrankungen auslösen?
Direkt selten — aber eine langfristig unausgewogene BARF-Ration kann Mangelerkrankungen verursachen, die sich wie Erkrankungen anderer Art manifestieren.

### Wo finde ich tierärztliche Ernährungsberater?
Über die Tierärztekammern, Tiermedizinische Universitäten oder Spezialkliniken mit Ernährungsabteilung.`,
