    content: `Rohe Knochen sind beim BARFen eine wichtige Komponente — als Kalziumquelle und als Beschäftigung. Aber sie sind kein risikoloses Spielzeug. Ohne Aufsicht kann ein Knochen zur Gefahr werden.

## Welche Risiken bestehen beim Knochengeben?

**Verschlucken von Knochenstücken:**
Hunde, die gierig fressen oder zu kleine Knochen bekommen, können Stücke abbrechen und verschlucken. Rohe Knochen splittern zwar selten so gefährlich wie gekochte, aber sie können brechen — und scharfkantige Fragmente im Magen-Darm-Trakt sind ein Notfall.

**Zahnbrüche:**
Sehr harte Knochen (Rinderbein, Markknochen, ausgehärtete Knochen) können Zähne brechen — besonders bei älteren Hunden oder aggressiven Kauern.

**Würgen und Steckenbleiben:**
Zu kleine Knochen können sich im Rachen oder Ösophagus festsetzen. Zeichen: Würgen, Speicheln, Unruhe, Panik.

**Verstopfung:**
Zu viele Knochenfragmente auf einmal können sich im Darm stauen.

## Was bedeutet „Aufsicht" beim Knochen?

- Du bist im gleichen Raum
- Du kannst eingreifen, bevor der Hund ein gefährliches Stück schluckt
- Du erkennst Zeichen von Würgen, Unruhe oder Schmerz sofort

Es reicht nicht, „in der Nähe zu sein" — du musst aktiv beobachten können.

## Was tun, wenn der Hund ein Stück verschluckt?

- **Kleines, weiches Fragment:** Oft problemlos — beobachten, ob normaler Kotabsatz erfolgt
- **Großes oder scharfes Stück:** Sofort Tierarzt oder Tierklinik aufsuchen
- **Würgen, Speicheln, Unruhe nach Knochen:** Immer als Notfall behandeln

## Häufige Fragen

### Muss ich bei jedem Kauen dabei sitzen?
Ja — solange dein Hund kaut, bist du dabei. Wenn er fertig ist und der Rest sicher ist (kein gefährliches Splitterrisiko mehr), kannst du ihn kurz alleine lassen.

### Wie lange darf der Knochen verfügbar sein?
Nimm den Knochen nach der Kausession weg. Im Kühlschrank ist ein rohes Knochenreste 1–2 Tage aufzubewahren.

### Sind alle Hunde gleich risikobelastet?
Nein. Aggressive, gierige Fresser und kleine Hunde haben ein höheres Risiko. Ruhige Kauer mit passenden Knochen sind weniger gefährdet.`,
