    imageAlt: "Knochen passend zur Hundegröße wählen",
    content: `Der passende Knochen hängt nicht von der eigenen Vorliebe ab — er hängt vom Hund ab. Größe, Kieferkraft, Kauverhalten und Alter bestimmen, welcher Knochen sicher und sinnvoll ist.

## Warum Knochen und Hund zusammenpassen müssen

Ein zu kleiner Knochen kann vollständig verschluckt werden — was bei einem kleinen Hund zu Ösophagus-Obstruktionen führen kann, bei einem großen Hund noch gefährlicher ist. Ein zu harter Knochen kann Zähne brechen — selbst bei Hunden mit starkem Gebiss.

Die Auswahl muss also zwei Kriterien gleichzeitig erfüllen:
1. **Groß genug**, dass er nicht vollständig verschluckt werden kann
2. **Weich genug**, dass er keine Zähne bricht

## Empfehlungen nach Hundegröße

**Kleine Hunde (unter 10 kg):**
- Hühnerhals, Putenrücken (nur mit Aufsicht), Lammrippchen
- Kein ganzer Hühnerschenkel (zu groß zum Abbeißen, Erstickungsgefahr)

**Mittelgroße Hunde (10–25 kg):**
- Hühner- oder Putenrücken, Lammhals, Kalbsrippen
- Rinderknie oder Rinderfüße (weich genug, groß genug)

**Große Hunde (über 25 kg):**
- Rinderfüße, Rinderhalse, Kalbshaxen
- Kein Rindermarkknochen (zu hart, Zahnbruchrisiko)

## Was du grundsätzlich vermeiden solltest

- **Ausgehärtete, alte Knochen** — werden mit der Zeit spröde und splittern gefährlicher
- **Beinabschnitte großer Tiere** für kleine Hunde
- **Alle gekochten Knochen** — ohne Ausnahme
- **Räucherknochen und aromatisierte Knochen** aus dem Handel — enthalten oft Zusätze

## Häufige Fragen

### Wie erkenne ich, ob ein Knochen zu hart ist?
Drücke mit dem Daumennagel dagegen. Gibt er gar nicht nach, ist er wahrscheinlich zu hart. Rohes Fleisch und knorpelreiche Knochen geben leicht nach.

### Was, wenn mein Hund den Knochen sofort zerkaut?
Beobachten, wie groß die Fragmente sind, die er schluckt. Wenn er sie in sicherer Größe schluckt: okay. Wenn er gierig ganze Stücke runterschluckt: anderen Knochen wählen.

### Muss ich den Knochen nach der Kausession wegnehmen?
Ja. Knochen, die lange in der Wohnung liegen, trocknen aus, werden härter und keimanfälliger.`,
