    imageAlt: "Hund hat Mühe beim Kotabsatz — Knochenkot beim BARFen",
    content: `Knochenfütterung beim BARFen ist wertvoll — aber der Köt zeigt dir, ob die Menge stimmt. „Knochenkot" ist der Begriff für weißlichen, harten, bröseligen Kot, der auf einen zu hohen Knochenanteil hinweist.

## Was Knochenkot bedeutet und wann es kritisch wird

Leicht weißlicher, sehr fester Kot nach Knochengabe ist noch im normalen Bereich. Problematisch wird es, wenn:

- Der Hund beim Kotabsatz würgt oder presst
- Er keinen Kot absetzen kann (Kotabsatzstopp)
- Er nach dem Kotabsatz unruhig oder schmerzhaft wirkt
- Der Kot extrem weiß, trocken und zerbröselt wie Kreide

## Was du sofort tun kannst

**Knochen aus der Ration nehmen:**
Für mindestens 3–5 Tage keine weiteren Knochen. Gibt den Darm Zeit, sich zu entleeren.

**Mehr Flüssigkeit:**
Mehr Wasser anbieten. Kürbis- oder Zucchinipüree als Feuchtezusatz.

**Bewegung:**
Moderate Bewegung stimuliert die Darmtätigkeit.

**Ballaststoffe:**
Etwas Kürbispüree oder Flohsamenschalen können helfen, den Kotabsatz zu erleichtern.

## Wann sofort zum Tierarzt?

- Kein Kotabsatz seit über 48 Stunden
- Hund zeigt Bauchschmerzen (gekrümmte Haltung, Winseln beim Berühren des Bauches)
- Auftreibung des Bauchs
- Erbrechen zusätzlich zu Kotabsatzproblemen

Das können Zeichen eines Darmverschlusses sein — das ist ein Notfall.

## Vorbeugen ist besser als reagieren

Die beste Vorbeugung: Knochenanteil von Anfang an korrekt dosieren (max. 10–15 % der Gesamtration) und nicht plötzlich sehr viele Knochen auf einmal geben.

## Häufige Fragen

### Wie lange dauert es, bis sich der Kot nach Knochenreduktion normalisiert?
Oft 2–3 Tage. Der Darm entleert sich schrittweise.

### Kann ich Olivenöl geben, um den Kotabsatz zu erleichtern?
In kleinen Mengen (½–1 TL) kann Olivenöl vorübergehend helfen. Kein Mineralöl (Paraffin) — das kann fettlösliche Vitamine binden.

### Ist Knochenkot bei jedem BARF-Hund normal?
Gelegentlich leicht festerer Kot ist normal. Anhaltend weißer, sehr harter Kot nie.`,
