    imageAlt: "Welpe, Adult und Senior — BARF nach Lebensphase",
    content: `Ein Hund ist kein statisches Wesen — sein Nährstoffbedarf ändert sich im Laufe des Lebens erheblich. Eine BARF-Ration, die für einen 3-jährigen Labrador passt, ist für einen 12-jährigen Labrador ebenso falsch wie für einen 3 Monate alten Labrador-Welpen.

## Die drei Lebensphasen im Überblick

### Welpen (bis zum Abschluss des Wachstums)
- **Höherer Energiebedarf** pro kg Körpergewicht (3–7 % je nach Alter und Rasse)
- **Kritische Kalzium-Phosphor-Balance:** Fehler führen zu Skelettproblemen — besonders bei großen Rassen
- **Häufigere Mahlzeiten:** 3–4x täglich bis 6 Monate, dann 2–3x täglich
- **Keine harten Knochen:** Das Gebiss und Kieferknochen sind noch nicht vollständig entwickelt

### Adulte Hunde (nach Wachstumsabschluss)
- **2–3 % des Körpergewichts** als Tagesration (je nach Aktivität anpassen)
- **Stabile, ausgewogene Ration** ist das Ziel
- **2 Mahlzeiten täglich** bei den meisten Hunden bewährt

### Senioren (ab ca. 7–10 Jahren je nach Rasse)
- **Geringerer Energiebedarf** — Grundumsatz sinkt
- **Gut verdauliche Proteine** bevorzugen
- **Gelenkunterstützung** durch Omega-3, Kollagen (aus Knorpel) kann sinnvoll sein
- **Weichere Komponenten** wenn Zähne oder Kieferkraft nachlassen

## Woran du merkst, dass die Lebensphase die Ration beeinflusst

- Welpe nimmt zu schnell/zu langsam zu → Menge und Zusammensetzung prüfen
- Adulter Hund verändert Gewicht ohne Aktivitätsänderung → Ration anpassen
- Senior wird trägem schläfriger, Fell ändert sich → Energiegehalt und Nährstoffzusammensetzung überdenken

## Häufige Fragen

### Ab wann ist ein Hund „Senior"?
Das ist rasseabhängig: Kleine Rassen ab ca. 9–10 Jahren, große Rassen ab ca. 6–7 Jahren. Körperliche Zeichen (Grauwerden, Trägheit) sind hilfreicher als das kalendarische Alter.

### Kann ich die Welpen-Ration selbst berechnen?
Theoretisch ja — aber Welpen-BARF ist das Riskanteste, was Einsteiger selbst berechnen können. Eine Fachberatung ist hier wirklich empfehlenswert.

### Brauchen Senioren andere Supplements?
Manchmal — z. B. Omega-3 für Gelenke, Vitamin D wenn die Syntheseleistung nachlässt, Probiotika für eine sensiblere Verdauung.`,
