    imageAlt: "Separates Schneidebrett für Rohfleisch — BARF-Hygiene",
    content: `Kreuzkontamination ist einer der häufigsten Hygienefehler in der Küche — und beim BARFen ist das Risiko besonders relevant, weil rohes Fleisch auf denselben Flächen verarbeitet wird, auf denen später menschliche Lebensmittel zubereitet werden.

## Was ist Kreuzkontamination?

Kreuzkontamination bedeutet, dass Keime von einem Lebensmittel auf ein anderes übertragen werden — in diesem Fall von rohem Hundefleisch auf Obst, Gemüse, Brot oder andere Lebensmittel, die ohne Erhitzen verzehrt werden.

Die Übertragung erfolgt durch:
- Dasselbe Schneidebrett (Keime in Ritzen und Poren)
- Dasselbe Messer
- Hände, die beides berühren
- Arbeitsflächen, die nicht zwischen den Verwendungen desinfiziert werden

## Die einfachste Lösung: Trennung

**Farbkodierung:** In vielen professionellen Küchen und inzwischen auch im Haushaltsbereich gibt es Schneidbretter in verschiedenen Farben. Rot = Rohfleisch, grün = Gemüse, etc.

**Separate Geräte:** Ein Messer und ein Schneidebrett ausschließlich für das Rohfleisch des Hundes. Sie kommen nie mit menschlichen Lebensmitteln in Berührung.

**Separate Lagerung:** Diese Geräte separat aufbewahren — in einer Schublade, Schachtel oder einem Behälter speziell für das Hundezubereitung.

## Was, wenn Trennung nicht möglich ist?

Wenn du nicht zwei komplette Sets haben möchtest, ist sofortige Reinigung nach dem Rohfleischkontakt die Alternative:

- Heiß abwaschen (≥ 60 °C) oder Spülmaschine (60–70 °C-Programm)
- Anschließend kurz desinfizieren (Lebensmitteldesinfektionsmittel oder verdünnte Essigsäure)
- Danach abtrocken und erst dann wieder für menschliche Lebensmittel verwenden

## Häufige Fragen

### Müssen die Geräte gespült oder auch desinfiziert werden?
Spülen bei hoher Temperatur reicht für die meisten Keime. Bei Sonderrisikogruppen im Haushalt (Kleinkinder, Schwangere) ist zusätzliche Desinfektion sinnvoll.

### Ist Plastik oder Holz besser für Schneidebretter bei Rohfleisch?
Plastik ist hygienischer, weil es keine Poren hat und in der Spülmaschine desinfiziert werden kann. Holz kann Keime in Ritzen halten, selbst nach dem Waschen.

### Was ist mit dem Napf selbst?
Der Napf muss nach jeder Rohfleischmahlzeit gründlich gereinigt werden — idealerweise mit heißem Wasser und Spülmittel oder in der Spülmaschine.`,
