    imageAlt: "Neue BARF-Komponente testen — Unverträglichkeit erkennen",
    content: `Beim BARFen hast du die volle Kontrolle über die Zutaten — das ist einer der größten Vorteile. Diesen Vorteil kannst du nur nutzen, wenn du weißt, wie dein Hund auf jede einzelne Komponente reagiert. Das geht nur durch systematisches Einführen.

## Warum einzeln einführen?

Wenn du fünf neue Zutaten gleichzeitig in die Ration gibst und dein Hund danach Durchfall hat, weißt du nicht, welche Zutat das Problem ist. Du hast keine Information gewonnen.

Wenn du dagegen jede neue Zutat einzeln einführst und mindestens 5–7 Tage beobachtest, lernst du:
- Was dein Hund gut verträgt
- Was Reaktionen auslöst
- Welche Sorten sein System gut aufnimmt

## Wie du neue Zutaten einführst

1. **Basis stabilisieren:** Erst wenn die aktuelle Ration problemlos funktioniert, neue Zutat einführen
2. **Klein anfangen:** 10–20 % der Mahlzeit als neue Komponente, Rest wie gewohnt
3. **Beobachtungszeit:** Mindestens 5–7 Tage mit derselben neuen Zutat
4. **Notizen:** Was hast du eingeführt? Was hat sich verändert?
5. **Eine Sache nach der anderen:** Keine zweite neue Zutat während der Beobachtungsphase

## Was du beobachtest

- **Kot:** Fest/weich, Farbe, Konsistenz, Menge
- **Haut und Fell:** Jucken, Rötungen, vermehrtes Kratzen
- **Energie:** Ungewöhnliche Müdigkeit oder Hyperaktivität
- **Erbrechen oder Würgen**
- **Pfoten lecken** (klassisches Zeichen für Futtelintoleranz)

## Besonders wichtig bei Verdacht auf Allergie

Wenn du vermutest, dass dein Hund auf etwas reagiert, ist das sequenzielle Einführen besonders wertvoll. In der Eliminationsdiät arbeitest du von einem Novel-Protein aus und führst Zutaten einzeln wieder ein — so identifizierst du Auslöser.

## Häufige Fragen

### Wie lange dauert eine vollständige Verträglichkeitsprüfung der BARF-Ration?
Wenn du 10–15 Zutaten prüfst: mehrere Monate. Das ist normal und lohnt sich.

### Was, wenn die Reaktion nach mehreren Tagen kommt?
Allergische Reaktionen können verzögert auftreten (bis zu 2 Wochen). Deshalb mindestens 7 Tage beobachten, bevor du eine Zutat als verträglich einstufst.

### Kann ich Unverträglichkeiten testen lassen?
Intradermal- oder Serum-Tests für Futtermittelallergien gibt es — aber Eliminationsdiäten gelten als zuverlässiger. Frag deinen Tierarzt.`,
