    imageAlt: "Frisches Rohfleisch zeitnah verfüttern",
    content: `Tiefgekühlt halten und beim Bedarf auftauen — das ist die richtige BARF-Praxis. Was nicht richtig ist: Rohfleisch aufzutauen und dann über mehrere Tage im Kühlschrank zu lagern, bevor es verfüttert wird.

## Warum aufgetautes Fleisch schnell weg muss

Nach dem Auftauen beginnen Bakterien sich zu vermehren — langsam im Kühlschrank, aber stetig. Je länger aufgetautes Fleisch im Kühlschrank liegt:
- Desto höher die Keimlast
- Desto größer das Risiko für Salmonellen, Campylobacter etc.
- Desto mehr verändert sich Textur und Geruch

**Faustregel:** Aufgetautes Rohfleisch sollte innerhalb von 24 Stunden verfüttert werden.

## Was die Frische des Fleisches beeinflusst

- **Wie es gefroren war:** Frisch gefriertes Fleisch in gutem Zustand hält sich nach dem Auftauen länger als bereits angetautes und wieder eingefrorenes
- **Kühlschranktemperatur:** Je näher an 0–2 °C, desto langsamer Keimwachstum
- **Ausgangsqualität:** Frisches Fleisch mit niedriger Ausgangs-Keimlast hält länger als bereits gealtertes Fleisch

## Wie du den Frischevorrang praktisch umsetzt

- **Plane die Portionen genau:** Immer nur so viel auftauen, wie du in 24 Stunden verfütterst
- **Morgens auftauen, abends verfüttern:** Einfaches System für einmal täglich Fütternde
- **Bei zwei Mahlzeiten:** Die zweite Portion separat einfrieren und morgens auftauen

## Was du mit nicht mehr ganz frischem Fleisch tun kannst

- Leicht ankochen — reduziert Keimlast erheblich und das Fleisch ist nicht mehr roh, aber immer noch verwertbar
- Wegwerfen, wenn Geruch oder Optik zweifelhaft sind

## Häufige Fragen

### Kann ich Rohfleisch auch 48 Stunden im Kühlschrank lassen?
Bei sehr frischem Ausgangsmaterial und sehr kaltem Kühlschrank (1–2 °C) gelegentlich vertretbar — aber 24 Stunden ist die sichere Faustregel.

### Was, wenn das Fleisch noch gut aussieht aber schon 3 Tage im Kühlschrank ist?
Nicht verfüttern. Keime sind nicht sichtbar — Aussehen und Geruch geben nur begrenzte Sicherheit.

### Wie erkenne ich verdorbenes Rohfleisch?
Süßlich-fauler Geruch, graue oder grünliche Verfärbung, Schleimschicht. Im Zweifel: wegwerfen.`,
