    imageAlt: "BARF-Ration: Richtiges Verhältnis von Fleisch, Knochen und Innereien",
    content: `BARF besteht nicht aus beliebig kombinierten Zutaten — es gibt eine bewährte Grundstruktur, die aus gutem Grund existiert. Wer die Proportionen dauerhaft verschiebt, riskiert Mängel oder Überversorgungen.

## Die klassische BARF-Aufteilung

Eine gängige Orientierung für erwachsene Hunde:
- **ca. 70 % Muskelfleisch** (verschiedene Sorten rotierend)
- **ca. 10–15 % fleischige Knochen** (oder äquivalente Kalziumquelle)
- **ca. 10 % Innereien** (davon max. 5 % Leber)
- **ca. 10–20 % pflanzliche Anteile** (Gemüse, Öle, Ergänzungen)

Diese Zahlen sind keine unumstößlichen Naturgesetze — sie sind ein bewährter Rahmen, der die wichtigsten Nährstoffgruppen abdeckt.

## Was bei dauerhaftem Ungleichgewicht passiert

**Zu viel Innereien (>20 %):**
Durchfall, Überversorgung mit Vitamin A, Leberschäden langfristig

**Zu wenig Knochen/Kalzium (<5 %):**
Kalziummangel, Knochenerweichung, Muskelschwäche

**Zu viel Knochen (>20 %):**
Hartkot, Verstopfung, Kalziumüberversorgung bei Welpen mit Skelettrisiko

**Kein Pflanzenteil:**
Fehlende Ballaststoffe, eventuelle Vitamin-Lücken

## Wie du das Verhältnis überwachst

- Berechne die Wochenration und prüfe die Gesamtmengen je Komponente
- Nutze eine einfache Tabelle oder BARF-App
- Beim nächsten Einkauf die Mengen entsprechend planen

## Darf ich variieren?

Ja — innerhalb des Rahmens ist Variation sinnvoll und erwünscht. Was sich nicht dauerhaft verschieben sollte, sind die Grundproportionen. Eine Woche mehr Innereien, nächste Woche weniger: kein Problem. Dauerhaft doppelt so viele Innereien wie geplant: Problem.

## Häufige Fragen

### Muss ich täglich die exakten Proportionen einhalten?
Nein — die Bilanz kann über eine Woche gemittelt werden. Einzelne Mahlzeiten dürfen variieren, der Wochendurchschnitt sollte stimmen.

### Was, wenn mein Hund bestimmte Komponenten verweigert?
Das ist häufig bei Gemüse und manchen Innereien. Finde Alternativen innerhalb derselben Nährstoffgruppe, anstatt die Komponente ganz wegzulassen.

### Gibt es eine offizielle BARF-Norm?
Nein — die Proportionen sind Empfehlungen, keine gesetzlichen Vorgaben. Ernährungsberater können individuelle Berechnungen erstellen.`,
