    imageAlt: "Rohes und gekochtes Futter nicht mischen beim Hund",
    content: `Die Mischfütterung von rohem und gekochtem Futter ist unter BARFern umstritten. Das Argument ist physiologisch: Rohes und Erhitztes verlässt den Magen unterschiedlich schnell — und wenn beide zusammen in einer Mahlzeit kommen, kann das die Verdauung belasten.

## Was passiert, wenn roh und gekocht gemischt werden?

Rohes Fleisch enthält natürliche Enzyme und wird vom Hundemagen mit niedrigem pH-Wert (stark sauer) schnell aufgeschlossen. Gekochtes Stärke (Reis, Kartoffeln, Gemüse) benötigt dagegen Amylase und einen anderen pH-Bereich.

Wenn beides gleichzeitig im Magen liegt, verlangsamt das die Magenentleerung. Das kann zu:
- Blähungen und Gasbildung führen
- Magenbeschwerden oder Erbrechen verursachen
- Den Keimabbau durch Magensäure weniger effizient machen

## Ist das eine gesicherte Wissenschaft?

Ehrlich gesagt: Die strenge physiologische Trennung ist unter Ernährungsexperten nicht vollständig konsensual. Viele Hunde vertragen gelegentliche Mischmahlzeiten problemlos. Dennoch ist das Prinzip biologisch plausibel, und für empfindliche Hunde ist Trennung eine sinnvolle Vorsichtsmaßnahme.

## Für wen ist Trennung besonders wichtig?

- Hunde mit empfindlicher Verdauung
- Hunde mit Blähungsneigung
- Hunde, die zu Gastritis neigen
- Ältere Hunde mit verlangsamter Magenentleerung

## Wie du es praktisch umsetzt

- **Mahlzeitenbasiert trennen:** Morgens Rohmahlzeit, abends (wenn gegeben) ggf. kleine Menge Gemüse oder Ergänzung
- **Zeitlicher Abstand:** Wenn du mischst, mindestens 4–6 Stunden zwischen roh und gekocht
- **Verzichtest auf stärkereiche Komponenten:** Reis, Brot, Nudeln gehören ohnehin nicht in eine BARF-Ration

## Häufige Fragen

### Darf ich püriertes Gemüse zur Rohmahlzeit geben?
Ja — rohes oder leicht gedämpftes Gemüse (nicht stärkereich, nicht gekochte Nudeln/Reis) wird anders bewertet als stärkereiches Gekochtes. Das ist kein Problem.

### Was ist mit gekochtem Kürbis zur BARF-Mahlzeit?
Meist unproblematisch — Kürbis ist kaum stärkehaltig und gut verträglich. Im Zweifelsfall separate Gabe.

### Ich mische seit Jahren problemlos — soll ich aufhören?
Wenn dein Hund keine Probleme hat, gibt es keinen akuten Handlungsbedarf. Das Prinzip der Trennung ist eine Vorsichtsmaßnahme, kein absolutes Gebot.`,
