    slug: "parasiten-in-rohem-fleisch",
    title: "Auf Parasiten in rohem Fleisch achten",
    shortDescription: "Manche Fleisch- und Fischsorten können Parasiten enthalten. Durchgefrieren reduziert das Risiko.",
    level: 2,
    tags: ["parasiten", "sicherheit"],
    imageUrl: "/images/tipps/barf/17.jpg",
    imageAlt: "Parasiten in rohem Fleisch — Sicherheit beim BARFen",
    content: `Rohes Fleisch kann Parasiten enthalten — Wurmlarven, Einzeller und andere Organismen, die für Hund und Mensch relevant sein können. Das ist kein Grund, BARF aufzugeben, aber ein Grund, es sicher zu handhaben.

## Welche Parasiten kommen in Rohfleisch vor?

**Toxoplasma gondii:**
Einzeller, der in rohem Fleisch (besonders Schwein, Schaf, Wild) vorkommt. Für immungeschwächte Hunde und schwangere Frauen relevant. Einfrieren tötet Toxoplasmen bei -18 °C nach 3 Tagen ab.

**Sarcocystis:**
Verwandt mit Toxoplasma, in ähnlichen Fleischsorten. Bei Hunden oft symptomlos.

**Trichinella:**
Hauptsächlich in Schwein und Wild. Deshalb: Schwein niemals roh, Wild immer gut durchfrieren oder garen.

**Anisakis (Fischparasit):**
In Seefisch (Hering, Makrele, Lachs) vorkommend. Durchfrieren bei -20 °C für mindestens 7 Tage tötet Larven ab. Alternativ: garen.

**Neospora caninum:**
Kann über rohes Rindfleisch übertragen werden, für Hunde harmlos, aber Übertragung auf Rinder möglich.

## Die Lösung: Durchfrieren

Ausreichendes Einfrieren ist die wirksamste präventive Maßnahme:
- **-18 °C für mindestens 3 Tage:** Tötet Toxoplasmen und viele andere Parasiten
- **-20 °C für mindestens 7 Tage:** Empfehlung für Fisch (Anisakis) und Wild (Trichinella)

Handelsübliche Tiefkühlgeräte erreichen -18 bis -24 °C. Prüfe die tatsächliche Temperatur mit einem Thermometer.

## Was ist mit Innereien?

Innereien (Leber, Niere, Lunge) können ebenfalls Parasiten enthalten. Einfrieren vor der Verfütterung ist empfehlenswert, besonders bei Wild-Innereien.

## Häufige Fragen

### Muss ich jedes Fleisch vor dem Verfüttern einfrieren?
Nicht zwingend, aber für Wild, Schwein (niemals roh!), Fisch und andere Risikosorten ist Durchfrieren dringend empfohlen.

### Schützt das Einfrieren gegen alle Parasiten?
Nein — manche sehr widerstandsfähigen Oozysten (z. B. Cryptosporidium) überleben Einfrieren. Gegen die meisten relevanten Parasiten ist Einfrieren jedoch wirksam.

### Was ist mit kommerziell tiefgekühltem Fleisch?
Wenn es bei ≤-18 °C für ausreichend lange Zeit eingefroren war, gilt dasselbe Prinzip. Frage beim Händler nach Einfriertemperatur und -dauer.`,
